routes.accessibility=['va-hisa','va-sah','va-sha','va-tra','il-senior-helpline','il-cil-access-living','il-cil-progress','il-cil-advocates-access','il-cil-drc','il-cil-iicil','il-cil-ivcil','il-cil-impact','il-cil-jacil','il-cil-lccil','il-cil-life','il-cil-linc','il-cil-nicil','il-cil-ofa','il-cil-options','il-cil-pace','il-cil-ramp','il-cil-sail','il-cil-sicil','il-cil-scil','il-cil-stone-hayes','il-cil-wcicil','va-location-finder',...DATA.filter(x=>x.regional_role==='aging_agency').map(x=>x.program_id)];
const seniorTopics={"daily": ["il-senior-helpline", "il-cil-access-living", "il-cil-progress", "il-cil-advocates-access", "il-cil-drc", "il-cil-iicil", "il-cil-ivcil", "il-cil-impact", "il-cil-jacil", "il-cil-lccil", "il-cil-life", "il-cil-linc", "il-cil-nicil", "il-cil-ofa", "il-cil-options", "il-cil-pace", "il-cil-ramp", "il-cil-sail", "il-cil-sicil", "il-cil-scil", "il-cil-stone-hayes", "il-cil-wcicil"], "accessibility": ["il-senior-helpline", "il-cil-access-living", "il-cil-progress", "il-cil-advocates-access", "il-cil-drc", "il-cil-iicil", "il-cil-ivcil", "il-cil-impact", "il-cil-jacil", "il-cil-lccil", "il-cil-life", "il-cil-linc", "il-cil-nicil", "il-cil-ofa", "il-cil-options", "il-cil-pace", "il-cil-ramp", "il-cil-sail", "il-cil-sicil", "il-cil-scil", "il-cil-stone-hayes", "il-cil-wcicil"], "vision": ["il-senior-helpline"], "hearing": ["il-senior-helpline"], "memory": ["alz-dementia-support", "il-senior-helpline"], "costs": ["il-ship", "il-senior-helpline", "il-legal-chicago", "il-legal-programs"], "rights": ["il-ombudsman", "il-legal-chicago", "il-legal-programs"]};
const ohioLiving=DATA.filter(x=>x.resource_role==='independent_living').map(x=>x.program_id),ohioCaregivers=DATA.filter(x=>x.resource_role==='caregiver_support').map(x=>x.program_id);
const ohioCenters=DATA.filter(x=>x.resource_role==='senior_center').map(x=>x.program_id);
const ohioHome=DATA.filter(x=>x.resource_role==='home_support').map(x=>x.program_id);
seniorTopics.daily.push(...ohioCenters);routes.local.push(...ohioCenters);
seniorTopics.daily.push(...ohioHome);routes.local.push(...ohioHome);routes.care.push(...ohioHome);
seniorTopics.daily.push(...ohioLiving,...ohioCaregivers);seniorTopics.accessibility.push(...ohioLiving);routes.accessibility.push(...ohioLiving);routes.local.push(...ohioLiving,...ohioCaregivers);routes.care.push(...ohioCaregivers,...ohioLiving);
routes.seniors=[...new Set(Object.values(seniorTopics).flat()),...DATA.filter(x=>x.regional_role).map(x=>x.program_id),'cms-care-compare'];
routes.community=DATA.filter(x=>['community_locator','senior_center'].includes(x.resource_role)).map(x=>x.program_id);
const routeNames={seniors:'Seniors and disability support',community:'Local posts and community connections',accessibility:'Ramps and home accessibility',priority:'Useful starting points',all:'All resources',benefits:'Help paying for care',survivors:'Surviving spouse support',care:'VA care and caregivers',rights:'Care concerns and rights',local:'Home and community support',housing:'Housing and service records'};
const regionalIDs=role=>DATA.filter(x=>x.regional_role===role).map(x=>x.program_id);
priority.push(...regionalIDs('aging_agency').filter(id=>!priority.includes(id)));
routes.local.push(...regionalIDs('aging_agency').filter(id=>!routes.local.includes(id)));
